1	//! Derived CLI definition covering dispatch between a declared subcommand
2	//! (`run`, aliased `r`) and plugin-provided external subcommands. Global
3	//! options (`--config`, repeatable `--define`) are only parsed before the
4	//! subcommand name; everything afterwards is captured verbatim. Results are
5	//! observed solely through `Cli::try_parse_from` with argv0 included.
6	#![allow(unreachable_pub)] // types stay observable to sibling test modules
7	
8	use clap::Args;
9	use clap::Parser;
10	use clap::Subcommand;
11	
12	fn parse_define(raw: &str) -> Result<String, String> {
13	    if raw.contains('=') {
14	        Ok(raw.to_owned())
15	    } else {
16	        Err(format!("invalid define `{raw}`: expected key=value"))
17	    }
18	}
19	
20	#[derive(Parser, Debug, PartialEq)]
21	#[command(
22	    name = "tool",
23	    about = "Root command dispatching to built-in and plugin subcommands",
24	    override_usage = "tool [OPTIONS] <COMMAND>"
25	)]
26	pub struct Cli {
27	    #[arg(long, global = true, default_value = "builtin.toml", value_name = "path")]
28	    pub config: String,
29	    #[arg(long, global = true, value_name = "key=value", value_parser = parse_define)]
30	    pub define: Vec<String>,
31	    #[command(subcommand)]
32	    pub command: Commands,
33	}
34	
35	#[derive(Subcommand, Debug, PartialEq)]
36	pub enum Commands {
37	    #[command(about = "Run a job", alias = "r")]
38	    Run(RunArgs),
39	    #[command(external_subcommand)]
40	    External(Vec<String>),
41	}
42	
43	#[derive(Args, Debug, PartialEq)]
44	#[command(override_usage = "tool run [OPTIONS] --output <path> [-- <TRAILING>...]")]
45	pub struct RunArgs {
46	    #[arg(long, value_name = "path", required = true)]
47	    pub output: String,
48	    #[arg(last = true)]
49	    pub trailing: Vec<String>,
50	}
51	
52	#[cfg(test)]
53	mod tests {
54	    use super::*;
55	    use clap::error::ErrorKind;
56	
57	    fn parse(argv: &[&str]) -> Result<Cli, clap::Error> {
58	        Cli::try_parse_from(argv)
59	    }
60	
61	    fn external_ok(argv: &[&str]) -> (String, Vec<String>, Vec<String>) {
62	        let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
63	        let Commands::External(tokens) = cli.command else {
64	            panic!("expected external subcommand for {argv:?}");
65	        };
66	        assert!(
67	            !tokens.is_empty(),
68	            "external capture must always include the command name: {argv:?}"
69	        );
70	        (cli.config, cli.define, tokens)
71	    }
72	
73	    fn run_ok(argv: &[&str]) -> (String, Vec<String>, RunArgs) {
74	        let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
75	        let Commands::Run(run) = &cli.command else {
76	            panic!("expected `run` parse for {argv:?}");
77	        };
78	        let run = RunArgs {
79	            output: run.output.clone(),
80	            trailing: run.trailing.clone(),
81	        };
82	        (cli.config, cli.define, run)
83	    }
84	
85	    #[test]
86	    fn run_requires_output_and_uses_defaults() {
87	        let (config, define, run) = run_ok(&["tool", "run", "--output", "out.txt"]);
88	        assert_eq!(config, "builtin.toml");
89	        assert_eq!(define, Vec::<String>::new());
90	        assert_eq!(run.output, "out.txt");
91	        assert_eq!(run.trailing, Vec::<String>::new());
92	    }
93	
94	    #[test]
95	    fn run_alias_r_enters_declared_command() {
96	        let (_, _, run) = run_ok(&["tool", "r", "--output", "out.txt"]);
97	        assert_eq!(run.output, "out.txt");
98	
99	        let (_, _, run) = run_ok(&[
100	            "tool", "r", "--output", "out.txt", "--", "a", "--flag",
101	        ]);
102	        assert_eq!(run.output, "out.txt");
103	        assert_eq!(run.trailing, vec!["a", "--flag"]);
104	    }
105	
106	    #[test]
107	    fn run_dispatch_validates_output_for_both_names() {
108	        for argv in [&["tool", "run"][..], &["tool", "r"][..]] {
109	            let err = parse(argv).unwrap_err();
110	            assert_eq!(err.kind(), ErrorKind::MissingRequiredArgument, "{argv:?}");
111	            let msg = err.to_string();
112	            assert!(msg.contains("--output"), "{argv:?}: {msg}");
113	            assert!(msg.contains("tool run"), "{argv:?}: {msg}");
114	        }
115	    }
116	
117	    #[test]
118	    fn run_prefix_is_external_not_inferred_subcommand() {
119	        let (_, _, tokens) = external_ok(&["tool", "ru", "--output", "x"]);
120	        assert_eq!(tokens, vec!["ru", "--output", "x"]);
121	    }
122	
123	    #[test]
124	    fn run_trailing_after_separator_is_raw_and_stays_in_run() {
125	        let (config, define, run) = run_ok(&[
126	            "tool",
127	            "run",
128	            "--output",
129	            "out.txt",
130	            "--",
131	            "plug",
132	            "--config",
133	            "other.toml",
134	            "run",
135	            "--",
136	            "",
137	        ]);
138	        assert_eq!(run.output, "out.txt");
139	        assert_eq!(
140	            run.trailing,
141	            vec!["plug", "--config", "other.toml", "run", "--", ""]
142	        );
143	        // Tokens after run's separator must not be reinterpreted as root state.
144	        assert_eq!(config, "builtin.toml");
145	        assert_eq!(define, Vec::<String>::new());
146	    }
147	
148	    #[test]
149	    fn run_rejects_positional_before_separator() {
150	        let err = parse(&["tool", "run", "--output", "o", "extra"]).unwrap_err();
151	        assert_eq!(err.kind(), ErrorKind::UnknownArgument);
152	        assert!(err.to_string().contains("extra"));
153	    }
154	
155	    #[test]
156	    fn external_command_captures_name_and_all_following_tokens() {
157	        let (_, _, tokens) = external_ok(&[
158	            "tool", "plug", "--flag", "run", "--output", "x", "r",
159	        ]);
160	        assert_eq!(
161	            tokens,
162	            vec!["plug", "--flag", "run", "--output", "x", "r"]
163	        );
164	    }
165	
166	    #[test]
167	    fn external_command_preserves_separator_and_empty_tokens() {
168	        let (_, _, tokens) = external_ok(&["tool", "plug", "--", ""]);
169	        assert_eq!(tokens, vec!["plug", "--", ""]);
170	
171	        let (_, _, tokens) = external_ok(&["tool", "plug", "", "--", ""]);
172	        assert_eq!(tokens, vec!["plug", "", "--", ""]);
173	    }
174	
175	    #[test]
176	    fn external_help_like_token_is_data() {
177	        let (_, _, tokens) = external_ok(&["tool", "plug", "--help", "--version"]);
178	        assert_eq!(tokens, vec!["plug", "--help", "--version"]);
179	    }
180	
181	    #[test]
182	    fn external_name_may_look_like_a_flag_after_root_escape() {
183	        let (_, _, tokens) = external_ok(&["tool", "--", "--flag", "x", "--"]);
184	        assert_eq!(tokens, vec!["--flag", "x", "--"]);
185	    }
186	
187	    #[test]
188	    fn external_name_can_be_empty() {
189	        let (_, _, tokens) = external_ok(&["tool", ""]);
190	        assert_eq!(tokens, vec![""]);
191	
192	        let (_, _, tokens) = external_ok(&["tool", "--", "", "rest"]);
193	        assert_eq!(tokens, vec!["", "rest"]);
194	    }
195	
196	    #[test]
197	    fn root_escape_dispatches_declared_name_to_external() {
198	        let (_, _, tokens) = external_ok(&["tool", "--", "run", "--output"]);
199	        assert_eq!(tokens, vec!["run", "--output"]);
200	
201	        let (_, _, tokens) = external_ok(&["tool", "--", "r"]);
202	        assert_eq!(tokens, vec!["r"]);
203	    }
204	
205	    #[test]
206	    fn global_options_parse_before_external_command() {
207	        let (config, define, tokens) = external_ok(&[
208	            "tool",
209	            "--config",
210	            "custom.toml",
211	            "--define",
212	            "a=1",
213	            "--define",
214	            "b=2",
215	            "plug",
216	            "arg",
217	        ]);
218	        assert_eq!(config, "custom.toml");
219	        assert_eq!(define, vec!["a=1", "b=2"]);
220	        assert_eq!(tokens, vec!["plug", "arg"]);
221	    }
222	
223	    #[test]
224	    fn global_options_after_external_name_are_captured() {
225	        let (config, define, tokens) = external_ok(&[
226	            "tool",
227	            "--config",
228	            "custom.toml",
229	            "plug",
230	            "--config",
231	            "stolen.toml",
232	            "--define",
233	            "c=3",
234	        ]);
235	        assert_eq!(config, "custom.toml");
236	        assert_eq!(define, Vec::<String>::new());
237	        assert_eq!(
238	            tokens,
239	            vec!["plug", "--config", "stolen.toml", "--define", "c=3"]
240	        );
241	    }
242	
243	    #[test]
244	    fn globals_beside_run_still_reach_run() {
245	        let (config, define, run) = run_ok(&[
246	            "tool",
247	            "run",
248	            "--config",
249	            "x.toml",
250	            "--output",
251	            "o",
252	            "--define",
253	            "k=v",
254	        ]);
255	        assert_eq!(config, "x.toml");
256	        assert_eq!(define, vec!["k=v"]);
257	        assert_eq!(run.output, "o");
258	    }
259	
260	    #[test]
261	    fn global_options_accept_equals_form_before_external_command() {
262	        let (config, define, tokens) = external_ok(&[
263	            "tool",
264	            "--config=custom.toml",
265	            "--define=a=1",
266	            "plug",
267	        ]);
268	        assert_eq!(config, "custom.toml");
269	        assert_eq!(define, vec!["a=1"]);
270	        assert_eq!(tokens, vec!["plug"]);
271	    }
272	
273	    #[test]
274	    fn root_escape_can_name_double_dash_itself() {
275	        // The first `--` ends option parsing; the second `--` is the command
276	        // name and the third is an ordinary argument.
277	        let (_, _, tokens) = external_ok(&["tool", "--", "--", "--"]);
278	        assert_eq!(tokens, vec!["--", "--"]);
279	    }
280	
281	    #[test]
282	    fn unknown_option_before_external_name_fails_on_that_token() {
283	        for argv in [
284	            &["tool", "--bogus", "plug"][..],
285	            &["tool", "--config", "c.toml", "--bogus", "plug"][..],
286	        ] {
287	            let err = parse(argv).unwrap_err();
288	            assert_eq!(err.kind(), ErrorKind::UnknownArgument, "{argv:?}");
289	            assert!(err.to_string().contains("--bogus"), "{argv:?}");
290	        }
291	
292	        let err = parse(&["tool", "-x", "plug"]).unwrap_err();
293	        assert_eq!(err.kind(), ErrorKind::UnknownArgument);
294	        assert!(err.to_string().contains("-x"));
295	    }
296	
297	    #[test]
298	    fn missing_option_value_before_external_name_fails() {
299	        for argv in [
300	            &["tool", "--config"][..],
301	            &["tool", "--define"][..],
302	            &["tool", "--config", "c.toml", "--define"][..],
303	        ] {
304	            let err = parse(argv).unwrap_err();
305	            assert_eq!(err.kind(), ErrorKind::InvalidValue, "{argv:?}");
306	            let msg = err.to_string();
307	            let needle = if argv[argv.len() - 1] == "--config" {
308	                "--config"
309	            } else {
310	                "--define"
311	            };
312	            assert!(msg.contains(needle), "{argv:?}: {msg}");
313	        }
314	    }
315	
316	    #[test]
317	    fn invalid_define_before_external_name_fails_on_value() {
318	        for argv in [
319	            &["tool", "--define", "nokey", "plug"][..],
320	            &["tool", "--define=nokey"][..],
321	        ] {
322	            let err = parse(argv).unwrap_err();
323	            assert_eq!(err.kind(), ErrorKind::ValueValidation, "{argv:?}");
324	            assert!(err.to_string().contains("nokey"), "{argv:?}");
325	        }
326	    }
327	
328	    #[test]
329	    fn invalid_define_after_external_name_is_captured_as_data() {
330	        let (_, define, tokens) = external_ok(&["tool", "plug", "--define", "nokey"]);
331	        assert_eq!(define, Vec::<String>::new());
332	        assert_eq!(tokens, vec!["plug", "--define", "nokey"]);
333	    }
334	
335	    #[test]
336	    fn root_help_succeeds_without_subcommand() {
337	        let err = parse(&["tool", "--help"]).unwrap_err();
338	        assert_eq!(err.kind(), ErrorKind::DisplayHelp);
339	        let help = err.to_string();
340	        for needle in ["--config", "--define", "builtin.toml", "key=value", "run"] {
341	            assert!(help.contains(needle), "root help missing {needle}:\n{help}");
342	        }
343	        // Subcommand-specific options must not leak into root help.
344	        assert!(!help.contains("--output"), "{help}");
345	        assert!(!help.trim_end().ends_with("--help"), "{help}");
346	    }
347	
348	    #[test]
349	    fn run_help_succeeds_without_output() {
350	        let err = parse(&["tool", "run", "--help"]).unwrap_err();
351	        assert_eq!(err.kind(), ErrorKind::DisplayHelp);
352	        let help = err.to_string();
353	        assert!(help.contains("--output"), "{help}");
354	        assert!(help.contains("tool run"), "{help}");
355	        // DisplayHelp proves `--help` selected help instead of being captured.
356	
357	        let err = parse(&["tool", "r", "--help"]).unwrap_err();
358	        assert_eq!(err.kind(), ErrorKind::DisplayHelp);
359	    }
360	
361	    #[test]
362	    fn help_after_failure_is_clean() {
363	        let err = parse(&["tool", "--bogus-flag"]).unwrap_err();
364	        assert_eq!(err.kind(), ErrorKind::UnknownArgument);
365	        assert!(err.to_string().contains("--bogus-flag"));
366	
367	        let help = parse(&["tool", "--help"]).unwrap_err();
368	        assert_eq!(help.kind(), ErrorKind::DisplayHelp);
369	        let help = help.to_string();
370	        assert!(!help.contains("--bogus-flag"), "{help}");
371	        assert!(!help.to_ascii_lowercase().contains("error"), "{help}");
372	    }
373	
374	    #[test]
375	    fn success_failure_success_calls_are_isolated() {
376	        // 1. external success
377	        let (config, define, tokens) = external_ok(&["tool", "plug", "--define", "x=1"]);
378	        assert_eq!(config, "builtin.toml");
379	        assert_eq!(define, Vec::<String>::new());
380	        assert_eq!(tokens, vec!["plug", "--define", "x=1"]);
381	
382	        // 2. invalid root input fails
383	        let err = parse(&["tool", "--config"]).unwrap_err();
384	        assert_eq!(err.kind(), ErrorKind::InvalidValue);
385	
386	        // 3. run success is unaffected by either previous call
387	        let (config, define, run) = run_ok(&["tool", "run", "--output", "o"]);
388	        assert_eq!(config, "builtin.toml");
389	        assert_eq!(define, Vec::<String>::new());
390	        assert_eq!(run.output, "o");
391	        assert_eq!(run.trailing, Vec::<String>::new());
392	    }
393	}
