    for argv in [
        &["tool", "run", "--output", "a", "--output", "b"][..],
        &["tool", "r", "--output", "a", "--output", "b"][..],
        &["tool", "--bogus"][..],
        &["tool", "run", "--bogus"][..],
        &["tool", "--config"][..],
        &["tool", "r"][..],
    ] {
        match Cli::try_parse_from(argv) {
            Ok(cli) => println!("OK   {argv:?} => {cli:?}"),
            Err(err) => println!("ERR  {argv:?} => {:?}\n{err}\n---", err.kind()),
        }
    }
}

