    // render byte-for-byte the same text after the intervening failure.
    let clean_root_help = parse(&["tool", "--help"]).unwrap_err().to_string();
    let clean_run_help = parse(&["tool", "run", "--help"]).unwrap_err().to_string();

    // 1. External success: explicit root state plus verbatim plugin tokens.
    let (config, define, tokens) = external_ok(&[
        "tool",
        "--config",
        "custom.toml",
        "--define",
        "a=1",
        "plug",
        "--flag",
        "run",
        "--",
        "",
    ]);
